            ctx.contentType("text/csv; charset=utf-8").result(csv);
        } catch (InvalidRequestException e) {
            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
        }
    }

    public void getTourismTaxReport(Context ctx) {
